                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      String(name),
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.market
                        ? `Rank ${payload[0].payload.rank}: ${payload[0].payload.market}`
                        : ""
                    }
                  />
                  <Area
                    type="monotone"
                    dataKey="cumulativeSharePct"
                    name="Cumulative share"
                    fill={ROSE}
                    fillOpacity={0.15}
                    stroke={ROSE}
                    strokeWidth={2}
                  />
                  {showEqualLine && (
                    <Line
                      type="monotone"
                      dataKey="equalSharePct"
                      name="Equal split"
                      stroke={SLATE}
                      strokeDasharray="4 4"
                      dot={false}
                      strokeWidth={1.5}
                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Ranked market shares"
            subtitle={
              ladderMetric === "sharePct"
                ? `% of ${vintage} world installations`
                : ladderMetric === "units"
                  ? "Annual installations (units)"
                  : "Cumulative share through this rank"
            }
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={ladderBars} layout="vertical" margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) =>
                      ladderMetric === "units" ? fmtUnits(v) : `${v}%`
                    }
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={64}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [
                      ladderMetric === "units"
                        ? fmtUnits(Number(v))
                        : fmtPct(Number(v), 1),
                      ladderMetric === "sharePct"
                        ? "Share"
                        : ladderMetric === "units"
                          ? "Units"
                          : "Cumulative",
                    ]}
                  />
                  <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                    {ladderBars.map((m) => (
                      <Cell key={m.market} fill={m.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "dual" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Dual-ledger tip comparison"
            subtitle="IFR install Top-1/Top-3 vs A3 NA auto / non-auto Q2 shares"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={DUAL_LEDGER_TIPS} margin={{ left: 8, bottom: 24 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    dataKey="metric"
                    tick={{ fontSize: 10 }}
                    interval={0}
                    angle={-18}
                    textAnchor="end"
                    height={50}
                  />
                  <YAxis
                    domain={[0, 80]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v, _n, props) => [
                      fmtPct(Number(v), 1),
                      props?.payload?.label ?? "Share",
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.ledger
                        ? String(payload[0].payload.ledger)
                        : ""
                    }
                  />
                  <Bar dataKey="valuePct" radius={[4, 4, 0, 0]}>
                    {DUAL_LEDGER_TIPS.map((d) => (
                      <Cell key={d.id} fill={d.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Binding tip meters"
            subtitle="Analytical score ??? install gravity vs NA order-book tip"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={BINDING_METERS} layout="vertical" margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                  />
                  <YAxis
                    type="category"
                    dataKey="label"
                    width={110}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v, _n, props) => [
                      Number(v).toFixed(1),
                      props?.payload?.note ?? "Score",
                    ]}
                  />
                  <Bar dataKey="score" radius={[0, 4, 4, 0]}>
                    {BINDING_METERS.map((d) => (
                      <Cell key={d.id} fill={d.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Install binding {HEADLINE.installBindingScore.toFixed(1)} vs NA
              order binding {HEADLINE.naOrderBindingScore.toFixed(1)} ??? same
              automation system, different concentration clocks.
            </p>
          </ChartCard>
        </div>
      )}

      {view === "path" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Top-1 / Top-3 / Asia share path"
            subtitle="Install meters through WR ??? prelim; 2026Q2 holds tip + NA non-auto overlay"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={pathData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[40, 85]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      v == null ? "???" : `${Number(v).toFixed(1)}%`,
                      String(name),
                    ]}
                  />
                  <Line
                    type="monotone"
                    dataKey="top1Pct"
                    name="Top-1 (China)"
                    stroke={ROSE}
                    strokeWidth={2.5}
                    dot={{ r: 4 }}
                  />
                  <Line
                    type="monotone"
                    dataKey="top3Pct"
                    name="Top-3"
                    stroke={AMBER}
                    strokeWidth={2}
                    dot={{ r: 3 }}
                  />
                  <Line
                    type="monotone"
                    dataKey="asiaPct"
                    name="Asia region"
                    stroke={SKY}
                    strokeWidth={2}
                    strokeDasharray="4 3"
                    dot={{ r: 3 }}
                  />
                  <Line
                    type="monotone"
                    dataKey="naNonAutoPct"
                    name="NA non-auto (A3)"
                    stroke={TEAL}
                    strokeWidth={2.5}
                    connectNulls={false}
                    dot={{ r: 5 }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Regional share donut"
            subtitle={`IFR regions ??? ${vintage === "2025" ? "2025 prelim" : "2024 WR"}`}
          >
            <div className="h-64 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={regionDonut}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={58}
                    outerRadius={95}
                    paddingAngle={2}
                    label={({ name, value }) => `${name} ${value}%`}
                  >
                    {regionDonut.map((d) => (
                      <Cell key={d.name} fill={d.fill} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v) => [`${v}%`, "Share"]} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="mt-2 flex flex-wrap justify-center gap-3">
              <ToggleGroup
                label="Donut vintage"
                value={vintage}
                onChange={setVintage}
                options={[
                  { id: "2024", label: "2024 WR" },
                  { id: "2025", label: "2025 prelim" },
                ]}
              />
            </div>
          </ChartCard>
        </div>
      )}

      {view === "na-book" && naLens === "bloc" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="NA Q2 order bloc shares"
            subtitle="Disclosed A3 auto vs non-automotive unit mix"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={NA_BLOC_SHARES}
                    dataKey="sharePct"
                    nameKey="label"
                    cx="50%"
                    cy="50%"
                    innerRadius={58}
                    outerRadius={95}
                    paddingAngle={3}
                    label={({ label, sharePct }) => `${label}: ${sharePct}%`}
                  >
                    {NA_BLOC_SHARES.map((d) => (
                      <Cell key={d.id} fill={d.fill} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v) => [`${v}%`, "Share"]} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Share ?? growth scatter (IFR installs)"
            subtitle="Market share vs YoY ??? China still the volume outlier"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ left: 8, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Share %"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="YoY %"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <ZAxis type="number" dataKey="z" range={[60, 400]} />
                  <ReferenceLine y={0} stroke={SLATE} strokeDasharray="3 3" />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      String(name),
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.short
                        ? String(payload[0].payload.short)
                        : ""
                    }
                  />
                  <Scatter data={scatterData}>
                    {scatterData.map((p) => (
                      <Cell key={p.short} fill={p.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "na-book" && naLens === "yoy" && (
        <div className="grid gap-6 lg:grid-cols-1">
          <ChartCard
            title={`NA industry ${yoyPeriod.toUpperCase()} YoY`}
            subtitle="A3 disclosed sector growth ??? semi/electro leads; auto OEM H1 deep negative"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={naYoyBars} margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <ReferenceLine y={0} stroke={SLATE} />
                  <Tooltip
                    formatter={(v) => [`${Number(v).toFixed(0)}%`, "YoY"]}
                  />
                  <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                    {naYoyBars.map((d) => (
                      <Cell key={d.industry} fill={d.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "na-book" && naLens === "cobot" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Cobot unit vs value share path"
            subtitle="A3 NA collaborative robots ??? unit share cooling into Q2 2026"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={COBOT_PATH}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="period" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 25]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      String(name),
                    ]}
                  />
                  <Bar
                    dataKey="unitSharePct"
                    name="Unit share"
                    fill="#8b5cf6"
                    radius={[4, 4, 0, 0]}
                  />
                  <Line
                    type="monotone"
                    dataKey="valueSharePct"
                    name="Value share"
                    stroke={AMBER}
                    strokeWidth={2.5}
                    dot={{ r: 4 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Cobot units by period"
            subtitle="Absolute collaborative units in the A3 NA book"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={COBOT_PATH}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="period" tick={{ fontSize: 11 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => fmtUnits(v)}
                  />
                  <Tooltip
                    formatter={(v) => [fmtUnits(Number(v)), "Units"]}
                  />
                  <Bar dataKey="units" radius={[4, 4, 0, 0]}>
                    {COBOT_PATH.map((d) => (
                      <Cell key={d.period} fill={d.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

